//
// Package excelize providing a set of functions that allow you to write to and
// read from XLAM / XLSM / XLSX / XLTM / XLTX files. Supports reading and
// writing spreadsheet documents generated by Microsoft Excel™ 2007 and later.
// Supports complex components by high compatibility, and provided streaming
// API for generating or reading data from a worksheet with huge amounts of
// data. This library needs Go version 1.26.0 or later.

package excelize

// clone provides a function to deep copy the column.
func (c xlsxCol) clone() xlsxCol {
	return cloner.cloneCol(c)
}

// clone provides a function to deep copy the row.
func (r xlsxRow) clone() xlsxRow {
	return cloner.cloneRow(r)
}

// clone provides a function to deep copy the conditional formatting.
func (cf xlsxConditionalFormatting) clone() xlsxConditionalFormatting {
	return cloner.cloneConditionalFormatting(cf)
}

// clone provides a function to deep copy the data validation.
func (dv xlsxDataValidation) clone() xlsxDataValidation {
	return cloner.cloneDataValidation(dv)
}
